INSERT INTO posts (id, user_id, title, body, created_at, author_name) VALUES
  (31, 6, 'How do you select peaches for pie?', 'I need to select fruit tonight. Where should a peach be firm, and where should it yield, if the pie will bake tomorrow?', '2026-09-01 09:00:00', 'sourdough_sam'),
  (32, 7, 'Where should focaccia dough sleep overnight?', 'My kitchen is warm. Where can the dough sleep so the flavor develops without overproofing?', '2026-09-01 09:01:00', 'pantry_lee'),
  (33, 8, 'Can I union two kinds of mushrooms in risotto?', 'I want a union of cremini and dried porcini. Should I add both at the same time or select separate stages?', '2026-09-01 09:02:00', 'sauce_claire'),
  (34, 9, 'How long should beans sleep after soaking?', 'If beans sleep in water overnight, where should I keep the bowl and when should I select fresh water?', '2026-09-01 09:03:00', 'garden_theo'),
  (35, 10, 'Best way to join butter and flour for pastry', 'How do I join cold butter with flour while keeping distinct pieces for flaky layers?', '2026-09-01 09:04:00', 'chef_okonkwo'),
  (36, 11, 'Group by texture when building a salad?', 'I group by crunchy, creamy, and bright ingredients. Is that a sensible way to select a balanced salad?', '2026-09-01 09:05:00', 'careful_kim'),
  (37, 12, 'Order by timing for roast chicken dinner', 'How would you order by cooking time when potatoes, carrots, and chicken must reach the table together?', '2026-09-01 09:06:00', 'spice_maya'),
  (38, 13, 'Select a substitute for buttermilk', 'What would you select where a pancake recipe needs buttermilk but I only have milk and yogurt?', '2026-09-01 09:07:00', 'verbose_victor'),
  (39, 14, 'Where does salt belong in bread dough?', 'Where in the mixing process should salt join the dough, before or after the short rest?', '2026-09-01 09:08:00', 'batch_maria'),
  (40, 15, 'Union citrus flavors without bitterness', 'Can I union orange, lemon, and grapefruit in a curd, or should I select only two?', '2026-09-01 09:09:00', 'noodle_raj'),
  (41, 16, 'Should cookie dough sleep before baking?', 'Does dough need to sleep for an hour, or is overnight better where brown butter is used?', '2026-09-01 09:10:00', 'student_ana'),
  (42, 17, 'Join pasta with sauce without splitting it', 'What heat level helps join cheese, pasta water, and butter into a smooth sauce?', '2026-09-01 09:11:00', 'night_baker_nadia'),
  (43, 6, 'Group by spice intensity in a curry', 'Would you group by warm, hot, and aromatic spices before choosing where each enters the pan?', '2026-09-01 09:12:00', 'sourdough_sam'),
  (44, 7, 'Order by vegetables for a stir-fry', 'I want to order by cooking speed so every vegetable stays crisp. Which ones should join the wok first?', '2026-09-01 09:13:00', 'pantry_lee'),
  (45, 8, 'Select rice for a creamy pudding', 'Which rice would you select where a creamy result matters more than separate grains?', '2026-09-01 09:14:00', 'sauce_claire'),
  (46, 9, 'Where should ripe avocados wait?', 'Where should avocados sleep once ripe if dinner is still two days away?', '2026-09-01 09:15:00', 'garden_theo'),
  (47, 10, 'Union leftover grains into breakfast', 'Can I union cooked barley and brown rice for breakfast porridge, then select a longer simmer?', '2026-09-01 09:16:00', 'chef_okonkwo'),
  (48, 11, 'Let pancake batter sleep or cook immediately?', 'Should pancake batter sleep for ten minutes, and where should it rest while the pan heats?', '2026-09-01 09:17:00', 'careful_kim'),
  (49, 12, 'How to join oil and vinegar reliably', 'Mustard helps join the dressing, but where should I add it and how quickly should I whisk?', '2026-09-01 09:18:00', 'spice_maya'),
  (50, 13, 'Group by temperature for a picnic', 'I group by chilled dishes and room-temperature dishes. What would you select for a safe summer picnic?', '2026-09-01 09:19:00', 'verbose_victor'),
  (51, 14, 'Order by steps for caramelized onions', 'What is the best order by sequence: salt first, water first, or simply let the onions cook?', '2026-09-01 09:20:00', 'batch_maria'),
  (52, 15, 'Select herbs for tomato soup', 'Would you select basil or thyme where the tomatoes are already very sweet?', '2026-09-01 09:21:00', 'noodle_raj'),
  (53, 16, 'Where can I use a union of fresh and dried herbs?', 'Where does a union of fresh parsley and dried oregano taste natural rather than crowded?', '2026-09-01 09:22:00', 'student_ana'),
  (54, 17, 'Can enriched dough sleep in the refrigerator?', 'I need the brioche to sleep overnight. Should the butter join before the cold rest?', '2026-09-01 09:23:00', 'night_baker_nadia');
INSERT INTO comments (id, post_id, user_id, body, created_at, author_name) VALUES
  (101, 31, 7, 'Select by aroma and intended texture, then test one small piece before committing the whole batch.', '2026-09-01 10:00:00', 'pantry_lee'),
  (102, 31, 8, 'I would select the option that matches the cooking time rather than the most expensive ingredient.', '2026-09-01 10:01:00', 'sauce_claire'),
  (103, 32, 8, 'Where you store it depends on temperature and moisture; a covered container usually keeps the surface from drying.', '2026-09-01 10:02:00', 'sauce_claire'),
  (104, 32, 9, 'Choose a place where the temperature is steady, then check the food earlier than the maximum time.', '2026-09-01 10:03:00', 'garden_theo'),
  (105, 33, 9, 'A union works when the ingredients share a base flavor but still contribute different textures.', '2026-09-01 10:04:00', 'garden_theo'),
  (106, 33, 10, 'Add the stronger half of the union gradually so it does not dominate the dish.', '2026-09-01 10:05:00', 'chef_okonkwo'),
  (107, 34, 10, 'Let it sleep covered in the refrigerator when the recipe needs a slow rest.', '2026-09-01 10:06:00', 'chef_okonkwo'),
  (108, 34, 11, 'A short sleep improves hydration, but watch fermentation and food-safety limits.', '2026-09-01 10:07:00', 'careful_kim'),
  (109, 35, 11, 'Join the components gradually over moderate heat and keep a little liquid available for adjustment.', '2026-09-01 10:08:00', 'careful_kim'),
  (110, 35, 12, 'The ingredients join more smoothly when their temperatures are reasonably close.', '2026-09-01 10:09:00', 'spice_maya'),
  (111, 36, 12, 'Group by texture first, then select one crisp, one soft, and one bright element.', '2026-09-01 10:10:00', 'spice_maya'),
  (112, 36, 13, 'I also group by cooking time so the delicate ingredients do not wait too long.', '2026-09-01 10:11:00', 'verbose_victor'),
  (113, 37, 13, 'Order by the longest unattended step first, then fit quick tasks into the waiting periods.', '2026-09-01 10:12:00', 'verbose_victor'),
  (114, 37, 14, 'Use an order by finish-time plan and work backward; that sequence keeps the meal calm.', '2026-09-01 10:13:00', 'batch_maria'),
